/** Actual loaded native item meshes, bounded warm reuse and continuous thin-block erosion. */
public final class NativeBlockRecipeRenderChecks {
 private static int checks;
 public static void run()throws Exception{
  for(ItemStack stack:List.of(new ItemStack(Items.STONE),new ItemStack(Items.GLASS),new ItemStack(Items.OAK_SLAB),new ItemStack(Items.OAK_TRAPDOOR),NativeBuilderProducts.result(0),NativeBuilderProducts.result(3),NativeBuilderProducts.result(4))){var full=draw(stack,1);need(!full.points.isEmpty(),"actual item mesh emitted "+stack);for(var p:full.points)need(Float.isFinite(p[0])&&Float.isFinite(p[1])&&Float.isFinite(p[2])&&p[0]>=-.001&&p[0]<=1.001&&p[1]>=-.001&&p[1]<=1.001&&p[2]>=-.001&&p[2]<=1.001,"normalized item bounds/padding "+stack);long builds=NativeBlockRecipePreview.builds();draw(stack,1);need(NativeBlockRecipePreview.builds()==builds,"warm item mesh reused "+stack);var half=draw(stack,.5f);need(!half.points.isEmpty(),"partial eroded mesh emitted "+stack);float top=NativeBlockRecipePreview.upperY(stack,.5f);for(var p:half.points)need(p[1]<=top+.00001,"actual geometry clipped at RF plane "+stack);}
  var slab=new ItemStack(Items.OAK_SLAB);need(NativeBlockRecipePreview.upperY(slab,.01f)<NativeBlockRecipePreview.upperY(slab,.5f)&&NativeBlockRecipePreview.upperY(slab,.5f)<NativeBlockRecipePreview.upperY(slab,.99f),"thin slab erodes throughout interval");need(draw(slab,0).points.isEmpty()&&!draw(slab,.01f).points.isEmpty(),"zero fraction empty and first fraction visible");need(NativeBlockRecipePreview.retainedBytes()<=4*1024*1024,"preview retained memory bounded");long before=NativeBlockRecipePreview.builds();NativeBlockRecipePreview.clear();draw(slab,1);need(NativeBlockRecipePreview.builds()==before+1,"resource invalidation rebuilds cached item");catalog();System.out.println("[vandorlabs][block-recipe-render] PASS checks="+checks+" actualVanilla+NativeMeshes/slabClipping/unitBounds/warmCache/invalidation");
 }
 private static void catalog()throws Exception{
  var mc=net.minecraft.client.Minecraft.getInstance();var chip=com.vandorlabs.neoforge.credentials.NativeChipTypes.variant("catalog");NativeBlockRecipeData.write(chip,new ItemStack(Items.GLASS),mc.level.registryAccess());var tag=new net.minecraft.nbt.CompoundTag();for(String key:List.of("Company","Logo","Output","Age","RejectedFor","Page"))tag.putInt(key,0);tag.putBoolean("Icon",true);tag.putBoolean("Occupied",true);tag.putBoolean("Master",false);tag.putLong("Sequence",0);tag.putLong("RejectedUntil",0);tag.put("Catalog",NativeBlockRecipeData.publicData(chip));tag.putString("CatalogName","Glass");var view=com.vandorlabs.neoforge.screen.NativeScreenChipView.read(tag);var renderer=new NativeScreenCatalogRenderer(mc.font);
  for(var kind:com.vandorlabs.render.ScreenSurface.Kind.values()){var out=new LinkedHashMap<RenderType,Recorder>();renderer.render(view,com.vandorlabs.render.ScreenSurface.quad(kind,false),new org.joml.Matrix4f(),new PoseStack(),type->out.computeIfAbsent(type,k->new Recorder()),0,0,0);int count=0;for(var values:out.values())count+=values.points.size();need(count>24&&out.containsKey(RenderType.entityTranslucentCull(net.minecraft.client.renderer.texture.TextureAtlas.LOCATION_BLOCKS)),"actual Catalog body glyphs and native item quad emitted "+kind);for(var values:out.values())for(var p:values.points)need(Float.isFinite(p[0])&&Float.isFinite(p[1])&&Float.isFinite(p[2]),"finite Catalog Screen preview "+kind);for(var values:out.values())for(int light:values.lights)need(light==0xf000f0,"Catalog content stays self-lit when ownerlight0 "+kind);}
  dispatch(view);
  need(renderer.retainedBytes()<=1024*1024,"Catalog captions/template cache bounded");NativeBlockRecipePreview.Lifecycle.logout(null);need(renderer.retainedBytes()==0&&NativeBlockRecipePreview.retainedBytes()==0,"actual logout lifecycle clears Catalog DTOs and item resources");
 }
 private static void dispatch(com.vandorlabs.neoforge.screen.NativeScreenChipView view)throws Exception{
  var mc=net.minecraft.client.Minecraft.getInstance();var context=new net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider.Context(mc.getBlockEntityRenderDispatcher(),mc.getBlockRenderer(),mc.getItemRenderer(),mc.getEntityRenderDispatcher(),mc.getEntityModels(),mc.font);var ber=new NativeScreenBlockEntityRenderer(context);var catalogField=NativeScreenBlockEntityRenderer.class.getDeclaredField("catalogs");catalogField.setAccessible(true);catalogField.set(ber,new NativeScreenCatalogRenderer(mc.font));var ownerField=NativeScreenBlockEntityRenderer.class.getDeclaredField("drawingOwner");ownerField.setAccessible(true);var surface=NativeScreenBlockEntityRenderer.class.getDeclaredMethod("surface",com.vandorlabs.neoforge.screen.NativeScreenRenderPlan.Binding.class,com.vandorlabs.neoforge.screen.NativeScreenEntity.Visual.class,com.vandorlabs.screen.ScreenFamily.State.class,int.class,com.vandorlabs.render.ScreenSurface.Quad.class,org.joml.Matrix4fc.class,PoseStack.class,MultiBufferSource.class,int.class,int.class,long.class);surface.setAccessible(true);var bake=new NativeScreenRenderer.Bake(NativePanelPlaybackRenderer.currentBake(),mc.getResourceManager());
  for(String id:List.of("programmable_diagonal_screen","programmable_console")){var block=(com.vandorlabs.neoforge.screen.NativeScreenBlock)net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("vandorlabs",id));var state=block.defaultBlockState();var owner=(com.vandorlabs.neoforge.screen.NativeScreenEntity)block.newBlockEntity(new net.minecraft.core.BlockPos(29000500,123,29000500),state);var tag=owner.saveWithoutMetadata(mc.level.registryAccess());tag.putInt("PrimarySurfaceTexture",-4);owner.loadWithComponents(tag,mc.level.registryAccess());var original=owner.visual();var visual=new com.vandorlabs.neoforge.screen.NativeScreenEntity.Visual(original.family(),original.settings(),original.frames(),original.glass(),original.controls(),original.effectivePower(),original.physicalPower(),original.inert(),original.geometryRevision(),original.appearance(),view,0);var plan=com.vandorlabs.neoforge.screen.NativeScreenRenderPlan.of(visual,block.screenState(state));need(plan.surfaces.stream().anyMatch(s->s.fragments().stream().anyMatch(f->f.binding()==com.vandorlabs.neoforge.screen.NativeScreenRenderPlan.Binding.CHIP)),"actual "+id+" RenderPlan selects CHIP");ownerField.set(ber,owner);var out=new LinkedHashMap<RenderType,Recorder>();int[] dispatched={0};NativeScreenRenderer.renderAt(bake,visual,block.screenState(state),com.vandorlabs.neoforge.screen.NativeScreenRenderProjection.SINGLE,new Object(),owner.getBlockPos(),new PoseStack(),type->out.computeIfAbsent(type,k->new Recorder()),0,OverlayTexture.NO_OVERLAY,0,(binding,current,facing,slot,content,transform,poses,buffers,light,overlay,time)->{try{if(binding==com.vandorlabs.neoforge.screen.NativeScreenRenderPlan.Binding.CHIP)dispatched[0]++;surface.invoke(ber,binding,current,facing,slot,content,transform,poses,buffers,light,overlay,time);}catch(ReflectiveOperationException failure){throw new IllegalStateException(failure);}});var model=out.get(RenderType.entityTranslucentCull(net.minecraft.client.renderer.texture.TextureAtlas.LOCATION_BLOCKS));need(dispatched[0]>0&&model!=null&&!model.points.isEmpty(),"real renderAt CHIP dispatcher reaches native Catalog model "+id);for(int light:model.lights)need(light==0xf000f0,"actual CHIP-dispatched Catalog model is self-lit "+id);ownerField.set(ber,null);}
  bake.clear();
 }
 private static Recorder draw(ItemStack stack,float fraction){var out=new Recorder();NativeBlockRecipePreview.render(stack,new PoseStack(),type->out,0xf000f0,OverlayTexture.NO_OVERLAY,fraction);return out;}
 private static final class Recorder implements VertexConsumer{final List<float[]> points=new ArrayList<>();final List<Integer> lights=new ArrayList<>();public VertexConsumer addVertex(float x,float y,float z){points.add(new float[]{x,y,z});return this;}public VertexConsumer setColor(int r,int g,int b,int a){return this;}public VertexConsumer setUv(float u,float v){return this;}public VertexConsumer setUv1(int u,int v){return this;}public VertexConsumer setUv2(int u,int v){lights.add(v<<16|u);return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}}
 private static void need(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}private NativeBlockRecipeRenderChecks(){}
}
